// Mechanical responses and synergy directions from the four active character pages and roster reference.
const tactics={
 raijin:{counters:[['Fermer la ligne','Un obstacle solide, notamment un pilier créé, bloque le tir. Le premier contact retire l’accélération de Surcharge.'],['Contrer au bon moment','Surtension reste contrable et conserve ses collisions : le ciblage ne garantit pas une touche.']],synergy:'Un partenaire ouvre une ligne ; Raijin exploite cette fenêtre avec son tir. Direction de coordination, sans binôme obligatoire.',zone:'Électrisation reste utilisable depuis la zone supérieure.',limit:'Seuil de Charges, vitesse, durée et courbure de l’Ultime restent à équilibrer.'},
 keplar:{counters:[['Modifier le terrain','Un changement tardif peut rendre sa trajectoire préparée moins pertinente.'],['Lire la dépense d’Expansion','Distorsion consomme toute l’Expansion : Keplar doit ensuite reconstruire sa ressource.']],synergy:'Un partenaire crée un obstacle ; Keplar peut construire une trajectoire qui le contourne avec Distorsion. Direction de conception.',zone:'L’utilité de Distorsion depuis la zone supérieure reste à définir.',limit:'Accumulation d’Expansion et rythme des changements de gravité restent à préciser.'},
 andaris:{counters:[['L’information ne joue pas à sa place','Connaître une trajectoire ne garantit pas de réussir le contre.'],['Une lecture à reconstruire','L’élimination d’un adversaire analysé remet à zéro l’Analyse accumulée sur lui.']],synergy:'Andaris révèle un prochain changement du terrain ; son partenaire adapte son placement ou son tir.',zone:'Le comportement précis de Vision persistante depuis la zone supérieure reste à préciser.',limit:'Seuil d’Analyse, durées et partage de Vision persistante avec l’allié restent ouverts.'},
 pandore:{counters:[['Le retour collectif','Lorsque toute l’équipe adverse revient ensemble, ses Malédictions restantes sont réinitialisées.'],['Une menace différée','Les marques ne donnent aucun avantage immédiat tant que leur cible n’est pas éliminée.']],synergy:'Une élimination maudite prolonge la supériorité numérique ; le partenaire peut exploiter cette fenêtre.',zone:'Son Sort reste à concevoir, avec une utilité requise depuis la zone supérieure.',limit:'Application, durée et plafond des marques à confirmer. Une purification reste une piste, pas un counter implémenté.'}
};
export function tacticsPanel(key){const t=tactics[key];return `<div class="tactics-intro"><span class="eyebrow">CONTRES & SYNERGIES</span><h2>${t?'Lire la réponse. Jouer ensemble.':'Un kit encore ouvert.'}</h2><p>Les contres viennent des mécaniques visibles, sans bonus automatique entre Types.</p></div>${t?`<div class="counter-list">${t.counters.map(([title,body],i)=>`<section><span aria-hidden="true">${i===0?'◇':'↗'}</span><div><h3>${title}</h3><p>${body}</p></div></section>`).join('')}</div><div class="synergy-note"><h3>Avec son binôme</h3><p>${t.synergy}</p></div><details class="tactics-more"><summary>Zone supérieure & points à tester</summary><p>${t.zone}</p><p>${t.limit}</p></details>`:`<p class="content-state">Contres et synergies à définir</p><p>Le nom, le Type et le rôle sont posés. Les capacités ne permettent pas encore d’établir des matchups fiables.</p><a class="text-action" href="/jeu/roles/?section=4">Comprendre les associations ↗</a>`}`;}
export function counterReminder(key){return `<button class="counter-reminder" data-open-tactics><span>↗</span><span><strong>Contres & synergies</strong><small>${tactics[key]?tactics[key].counters.map(c=>c[0]).join(' · '):'Interactions à définir avec le futur kit'}</small></span></button>`;}
